          "主角": { "姓名": [ "<user>", "主角的姓名。" ], "年龄": [ 0, "主角的当前年龄。" ], "身份": [ "(无)", "主角的社会身份或头衔。" ], "力量层次": [ "(未定义)", "描述主角当前的实力，格式为：等级(层级名)。" ], "资源": { "生命值": [ 100, "建议设置合理的初始值" ], "生命值上限": [ 100, "建议设置合理的初始值" ], "法力值": [ 50, "建议设置合理的初始值" ], "法力值上限": [ 50, "建议设置合理的初始值" ], "体力值": [ 100, "体力值" ], "体力值上限": [ 100, "体力值上限" ] }, "装备": [ { "武器": [ "(无)", "" ], "盔甲": [ "(无)", "" ], "饰品": [ "(无)", "" ] } ], "状态效果": [ { "$meta": { "extensible": true } } ], "技能": [ { "$meta": { "extensible": true } } ] },
