        // --- [ 3. 日常 UI 渲染器 (移植自 Royal V13) ] ---

        function renderStatusUI(data) { 
            const container = document.getElementById('chessboard-container-wrapper'); 
            if (!container) { console.error("[RoyalUI V15] 日常UI Wrapper 'chessboard-container-wrapper' not found!"); return; }

            container.className = 'status-container'; 

            const sectionIcons = { '主角': 'fa-book-skull', '探索附近': 'fa-compass', '人脉关系': 'fa-users-viewfinder', '命运系统': 'fa-hands-holding-circle', '当前任务': 'fa-scroll', '财产': 'fa-gem', '今日新闻': 'fa-newspaper', '世界图鉴': 'fa-atlas' }; 
            const sectionOrder = ['主角', '探索附近', '人脉关系', '命运系统', '当前任务', '财产', '今日新闻', '世界图鉴']; 
            let sectionsHtml = sectionOrder.map(title => { const iconClass = sectionIcons[title] || 'fa-question-circle'; const sectionId = { '主角': 'protagonist-section', '探索附近': 'map-section', '人脉关系': 'contacts-section', '命运系统': 'destiny-section', '当前任务': 'tasks-section', '财产': 'assets-section', '今日新闻': 'news-section', '世界图鉴': 'codex-section' }[title]; const contentPadding = (title === '主角') ? 'padding: 5px 15px 15px 15px;' : ''; return `<details class="section"> <summary><i class="fa-solid ${iconClass} fa-fw summary-icon"></i>${title}<span class="arrow-toggle">&gt;</span></summary> <div class="section-content" id="${sectionId}" style="${contentPadding}"></div> </details>`; }).join(''); 
