                skills = SafeGetValue(fullData, `人脉关系[0].${key}.技能[0]`, {});
                if (Object.keys(skills).length <= 1) { 
                    skills = SafeGetValue(fullData, `命运系统.红线对象[0].${key}.技能[0]`, {}); 
                }
                items = SafeGetValue(fullData, `人脉关系[0].${key}.背包[0]`, {});
                 if (Object.keys(items).length <= 1) {
                    items = SafeGetValue(fullData, `命运系统.红线对象[0].${key}.背包[0]`, {});
                }
                // (此方: 敌人(enemies)的技能/背包目前设计中不会显示，所以这里OK)
            }

            return { skills, items };
        }

        function renderBattleUI(data) {
            const wrapper = document.getElementById('battle-ui-wrapper');
            if (!wrapper) { console.error("[MasterUI] Battle UI wrapper not found!"); return; }
            const playerArea = document.getElementById('player-combatants-area');
            const enemyArea = document.getElementById('enemy-combatants-area');
            const playerPlaceholder = document.getElementById('player-combatants-placeholder');
            const enemyPlaceholder = document.getElementById('enemy-combatants-placeholder');

            playerArea.innerHTML = '<div class="team-title">光の盟友</div>';
            enemyArea.innerHTML = '<div class="team-title">深淵の敵</div>';

            const alliesObj = SafeGetValue(data, '战斗状态[0].allies', {});
            const enemiesObj = SafeGetValue(data, '战斗状态[0].enemies', {});

            const allyKeys = Object.keys(alliesObj).filter(k => k !== '$meta');
            const enemyKeys = Object.keys(enemiesObj).filter(k => k !== '$meta');

            // (此方: 修正了selectedParticipantKey的逻辑，防止它选中不存在的单位)
            if (!alliesObj[selectedParticipantKey] && !enemiesObj[selectedParticipantKey]) {
                selectedParticipantKey = allyKeys.length > 0 ? allyKeys[0] : (enemyKeys.length > 0 ? enemyKeys[0] : null);
            }

            let playerUnitsFound = 0;
            allyKeys.forEach(key => {
                const unit = alliesObj[key];
                if (typeof unit !== 'object' || unit === null) return;
                const name = SafeGetValue(unit, '名称[0]', key);
                const type = (key === '主角' ? '主角' : '友军');
                const hp_val = SafeGetValue(unit, '生命值[0]', 0); 
                const hp_max = SafeGetValue(unit, '生命值上限[0]', 100);
                const mp_val = SafeGetValue(unit, '法力值[0]', 0);
                const mp_max = SafeGetValue(unit, '法力值上限[0]', 100);
                const hp_perc = hp_max > 0 ? (hp_val / hp_max) * 100 : 0;
                const mp_perc = mp_max > 0 ? (mp_val / mp_max) * 100 : 0;
                const isSelected = (key === selectedParticipantKey); 

                let barHtml = `<div class="combatant-bar ${isSelected ? 'selected' : ''}" data-key="${key}"> 
                                <div class="combatant-header">
                                    <span class="combatant-name">${name}</span>
                                    <span class="combatant-type">${type}</span>
                                </div>
                                <div class="stat-bars">
                                    <div class="stat-bar"><div class="stat-bar-value hp" style="width: ${hp_perc}%;"></div><div class="stat-bar-text"><span class="label">命:</span> ${hp_val} / ${hp_max}</div></div>
                                    <div class="stat-bar"><div class="stat-bar-value mp" style="width: ${mp_perc}%;"></div><div class="stat-bar-text"><span class="label">法:</span> ${mp_val} / ${mp_max}</div></div>
                                </div>
                             </div>`;
                playerArea.innerHTML += barHtml; 
                playerUnitsFound++;
            });

            let enemyUnitsFound = 0;
            enemyKeys.forEach(key => {
                const unit = enemiesObj[key];
                if (typeof unit !== 'object' || unit === null) return;
                const name = SafeGetValue(unit, '名称[0]', key);
                const type = '敌军';
                const hp_val = SafeGetValue(unit, '生命值[0]', 0); 
                const hp_max = SafeGetValue(unit, '生命值上限[0]', 100);
                const hp_perc = hp_max > 0 ? (hp_val / hp_max) * 100 : 0;
                const isSelected = (key === selectedParticipantKey); 

                let barHtml = `<div class="combatant-bar ${isSelected ? 'selected' : ''}" data-key="${key}"> 
                                <div class="combatant-header">
                                    <span class="combatant-name">${name}</span>
                                    <span class="combatant-type">${type}</span>
                                </div>
                                <div class="stat-bars">
                                    <div class="stat-bar"><div class="stat-bar-value hp" style="width: ${hp_perc}%;"></div><div class="stat-bar-text"><span class="label">命:</span> ${hp_val} / ${hp_max}</div></div>
                                </div>
                             </div>`;
                enemyArea.innerHTML += barHtml; 
                enemyUnitsFound++;
            });


            if (playerUnitsFound === 0) playerArea.appendChild(playerPlaceholder.cloneNode(true)); 
            if (enemyUnitsFound === 0) enemyArea.appendChild(enemyPlaceholder.cloneNode(true)); 

            const tabContentArea = document.getElementById('tab-content-area');
            tabContentArea.innerHTML = '';

            document.getElementById('tab-btn-skills').classList.toggle('active-tab', currentCombatTab === 'skills');
            document.getElementById('tab-btn-bags').classList.toggle('active-tab', currentCombatTab === 'bags');

            // (此方: 只有盟友(ally)和主角(player)被选中时才显示技能和背包)
            const selectedUnitIsAlly = alliesObj.hasOwnProperty(selectedParticipantKey);
            if (selectedUnitIsAlly) {
                const { skills, items } = getParticipantData_v15(selectedParticipantKey, data);
                if (currentCombatTab === 'skills') {
                    const skillKeys = Object.keys(skills).filter(k => k !== '$meta');
                    if (skillKeys.length > 0) {
                        skillKeys.forEach(key => {
                            const skill = skills[key];
                            if (typeof skill !== 'object' || skill === null) return;
                            const name = SafeGetValue(skill, '名称[0]', key);
                            const cost = SafeGetValue(skill, 'cost[0]', '无消耗');
                            const desc = SafeGetValue(skill, '描述[0]', '暂无描述。');
                            tabContentArea.innerHTML += `<button class="action-item-button" onclick="window.battle_ui_events.useSkill('${name}', '${key}')"><div><div class="action-item-name">${name}</div><div class="action-item-desc">${desc}</div></div><div class="action-item-cost">${cost}</div></button>`;
                        });
                    } else { tabContentArea.innerHTML = '<p class="empty-state-text">(未习得奥義)</p>'; }
                } else { 
                    const bagKeys = Object.keys(items).filter(k => k !== '$meta');
                    if (bagKeys.length > 0) {
                        let itemsFound = 0;
                        bagKeys.forEach(key => {
                            const item = items[key];
                            if (typeof item !== 'object' || item === null) return;
                            const name = SafeGetValue(item, '名称[0]', key);
                            const count = SafeGetValue(item, '数量[0]', 0);
                            const desc = SafeGetValue(item, '描述[0]', '暂无描述。');
                            if (count <= 0) return; 
                            tabContentArea.innerHTML += `<button class="action-item-button" onclick="window.battle_ui_events.useItem('${name}', '${key}')"><div><div class="action-item-name">${name}</div><div class="action-item-desc">${desc}</div></div><div class="action-item-count">x ${count}</div></button>`;
                            itemsFound++;
                        });
                        if (itemsFound === 0) { tabContentArea.innerHTML = '<p class="empty-state-text">(次元袋空空如也)</p>'; }
                    } else { tabContentArea.innerHTML = '<p class="empty-state-text">(次元袋空空如也)</p>'; }
                }
            } else {
                tabContentArea.innerHTML = '<p class="empty-state-text">(无法探知敌人的行动...)</p>';
            }

            const preInputEl = document.getElementById('pre-input-bar');
            const logEl = document.getElementById('battle-log-content');

            if (preInputEl.value.trim() === '') { preInputEl.value = ""; } 

            let combatLog = SafeGetValue(data, '战斗状态[0].combat_log', []); 
            if (Array.isArray(combatLog) && combatLog.length > 0 && !Array.isArray(combatLog[0])) {
                 combatLog = [SafeGetValue(data, '战斗状态[0].combat_log[0]', '(战斗日志)')];
            } else if (!Array.isArray(combatLog)) {
                 combatLog = [String(combatLog)];
            }
            logEl.innerHTML = combatLog.length > 0 ? combatLog.slice(-10).map(log => `<p>${log}</p>`).join('') : `<p class="empty-state-text">(战况...一片寂静...)</p>`;

            logEl.scrollTop = logEl.scrollHeight;

            const endBattleOverlay = document.getElementById('end-battle-overlay');
            const uiMode = SafeGetValue(data, 'UI状态.当前界面[0]', '日常'); 
            if (uiMode === '战斗' && enemyKeys.length === 0 && allyKeys.length > 0) { endBattleOverlay.classList.remove('hidden'); } 
            else { endBattleOverlay.classList.add('hidden'); }
        }

        // --- [ 5. 主渲染路由 (移植自 Sanguo) ] ---
        function Master_Render_UI(data) {
            if (!data || typeof data !== 'object') {
                console.warn("[RoyalUI V15] Master_Render_UI 收到无效数据。");
                return;
            }
            window.last_stat_data = data; 

            const uiMode = SafeGetValue(data, 'UI状态.当前界面[0]', '日常');

            setToggle('chessboard-container-wrapper', uiMode === '日常');
            setToggle('battle-ui-wrapper', uiMode === '战斗');

            document.body.classList.toggle('status-mode', uiMode === '日常');
            document.body.classList.toggle('combat-mode', uiMode === '战斗');

            if (uiMode === '日常') {
                renderStatusUI(data); 
            } else {
                renderBattleUI(data); 
            }
        }

        // --- [ 6. 核心初始化 (移植自 Sanguo) ] ---
        async function Master_Init() {
            console.log("--- [RoyalUI V15] Master_Init 启动 ---");
            try {
                const hasChat = typeof getChatMessages === 'function' && typeof getCurrentMessageId === 'function';
                const msgs = hasChat ? await getChatMessages(getCurrentMessageId()) : []; 
                const data = msgs?.[0]?.data?.stat_data; 

                let mergedData;
                if (data && typeof data === 'object') {
                    console.log("[RoyalUI V15] 发现 stat_data。与默认值(V9)合并。");
                    mergedData = deepMerge(defaultEmptyState, data); 
                } else {
                    console.warn('[RoyalUI V15] 未发现 stat_data。使用默认空状态(V9)。');
                    mergedData = defaultEmptyState;
                }

                Master_Render_UI(mergedData); 
                console.log("--- [RoyalUI V15] Master_Init 完成 ---");

                document.addEventListener('click', function(event) {
                    const target = event.target;
                    const combatWrapper = document.getElementById('battle-ui-wrapper');

                    if (combatWrapper && !combatWrapper.classList.contains('hidden')) {
                        const combatantBar = target.closest('.combatant-bar[data-key]');
                        if (combatantBar) {
                            const newKey = combatantBar.dataset.key;
                            if (newKey !== selectedParticipantKey) {
                                console.log("[MasterUI] 切换战斗目标 (本地):", newKey);
                                selectedParticipantKey = newKey;
                                renderBattleUI(window.last_stat_data); 
                            }
                            return; 
                        }
                    }

                    const statusContainerVisible = !document.getElementById('chessboard-container-wrapper')?.classList.contains('hidden');
                    if (statusContainerVisible) {
                        const filterBtn = target.closest('.filter-btn[data-filter-type]'); 
                        if (filterBtn) { const filterType = filterBtn.dataset.filterType; const filterValue = filterBtn.dataset.filterValue; if (filterType === 'inventory') { currentInventoryFilter = filterValue; populateAssets(SafeGetValue(window.last_stat_data, '财产', {})); } return; }

                        const actionTargetNonCombat = target.closest('.action-button[data-action]'); 
                        if (actionTargetNonCombat) { const action = actionTargetNonCombat.dataset.action; const location = actionTargetNonCombat.dataset.location; const itemNameNonCombat = actionTargetNonCombat.dataset.itemName; if (action === 'travel' && location) { sendCommand(`/send 前往 ${location} |/trigger`); return; } else if (action === 'update-news') { sendCommand(`/send 更新\"每日新闻\" |/trigger`); return; } }

                        const protagonistTab = target.closest('.protagonist-tab[data-tab]'); 
                        if (protagonistTab) { const newTab = protagonistTab.dataset.tab; if (newTab !== currentProtagonistTab) { currentProtagonistTab = newTab; populateProtagonist(SafeGetValue(window.last_stat_data, '主角', {})); } return; }
                    }
                });

            } catch (e) {
                console.error('CRITICAL Error during [RoyalUI V15] Master_Init:', e);
                const wrapper = document.getElementById('chessboard-container-wrapper');
                if(wrapper) wrapper.innerHTML = `<p style='color:red;'>状态栏加载出错: ${e.message}</p>`;
            }
        }

        // --- [ 7. 核心事件监听 (移植自 Sanguo) ] ---
        if (typeof waitGlobalInitialized === 'function') {
            console.log("[RoyalUI V15] 等待 Mvu 初始化...");
            waitGlobalInitialized('Mvu').then(() => {
                console.log("[RoyalUI V15] Mvu 已初始化. 调用 Master_Init 并设置 *唯一* 监听器。");
                Master_Init(); 

                eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, m => {
                    if (m && m.stat_data && typeof m.stat_data === 'object') {
                        Master_Render_UI(m.stat_data); 
                    } else {
                        console.warn('[RoyalUI V15] 收到 VARIABLE_UPDATE_ENDED 事件，但 stat_data 无效。');
                    }
                });
            }).catch(error => {
                console.error('[RoyalUI V15] 等待 Mvu 初始化时出错:', error);
                document.addEventListener('DOMContentLoaded', Master_Init);
            });
        } else {
            console.warn('[RoyalUI V15] waitGlobalInitialized 未找到。在 DOMContentLoaded 上加载。');
            document.addEventListener('DOMContentLoaded', Master_Init);
        }

    })();
</script>
